import {migrateCollection,ensureCollection,heroCardRank} from './collection.js';
import {HEROES} from './content.js';
export const DEFAULT_SAVE={coins:0,vitality:0,power:0,reload:0,best:0,careerXp:0,gpower:0,fpower:0,epower:0,ipower:0,fskill:0,eskill:0,iskill:0};
export function migrateSave(raw){const out={...DEFAULT_SAVE};if(raw&&typeof raw==='object')for(const k of Object.keys(out))if(Number.isFinite(raw[k])&&raw[k]>=0)out[k]=Math.min(Math.floor(raw[k]),['coins','careerXp'].includes(k)?1e9:k==='best'?10:8);out.heroes={};if(raw?.heroes&&typeof raw.heroes==='object')for(const [id,r] of Object.entries(raw.heroes)){if(!/^[a-z][a-z0-9-]{0,63}$/.test(id)||!r||typeof r!=='object')continue;out.heroes[id]={};for(const k of ['xp','seconds','score','runs'])out.heroes[id][k]=Number.isFinite(r[k])?Math.min(1e9,Math.max(0,Math.floor(r[k]))):0;}out.collection=migrateCollection(raw?.collection);return out;}
export function careerProgress(total){let level=1,needed=150;total=Math.max(0,Math.floor(total));while(total>=needed&&level<10000){total-=needed;level++;needed=150+(level-1)*75;}return {level,xp:total,needed,percent:Math.min(100,total/needed*100)};}
export function settleRun(save,game){if(game.settled)return game.settled;game.flushLoot();const bonus=game.state==='won'?100:0;const coins=game.gold+bonus;const previous=careerProgress(save.careerXp);save.coins+=coins;save.careerXp+=game.totalXp;save.best=Math.max(save.best,game.wave);save.heroes??={};const heroes=game.team.map(h=>{const previous=heroProgress(save,h.id);const r=save.heroes[h.id]??={xp:0,seconds:0,score:0,runs:0};const score=Math.floor(h.runScore||0),seconds=Math.floor(h.activeSeconds||0);const xp=score+Math.min(Math.floor(seconds/8),score);r.xp+=xp;r.score+=score;r.seconds+=seconds;if(score>0)r.runs++;return {id:h.id,name:h.name,xp,previous,current:heroProgress(save,h.id)};});const keys=game.keyFragments||0;ensureCollection(save).keys+=keys;game.settled={keys,heroes,coins,bonus,xp:game.totalXp,previous,current:careerProgress(save.careerXp),bosses:game.bossKills};return game.settled;}
export const SHOP=[
 {key:'vitality',name:'גדר מחוזקת',group:'general',base:40,icon:'◇',desc:'40 נקודות הגנה נוספות למצודה בכל דרגה. נשמר לכל הריצות.',unit:'הגנה',value:l=>650+l*40},
 {key:'power',name:'אימון הצוות',group:'general',base:55,icon:'✦',desc:'5% לנזק הבסיסי של כל הצוות בכל דרגה. חל גם על גיבורים שיגויסו בהמשך.',unit:'% נזק',value:l=>100+l*5},
 ...['gpower','fpower','epower','ipower'].map((key,hero)=>({key,hero,group:'heroes',name:'שליטה במתקפה',base:40,icon:'✦',desc:'8% לנזק הבסיסי של הגיבור בכל דרגה. ההכשרה נשארת גם כשהריצה מסתיימת.',unit:'% נזק אישי',value:l=>100+l*8})),
 {key:'reload',hero:0,group:'heroes',name:'טעינה טקטית',base:45,icon:'ϟ',desc:'5% למהירות החלפת המחסנית בכל דרגה. שדרוגי הטעינה הקיימים שלכם נשמרו כאן.',unit:'% מהירות טעינה',value:l=>100+l*5},
 {key:'fskill',hero:1,group:'heroes',name:'לב הלהבה',base:55,icon:'✹',desc:'השריפה מתחזקת ב־3 נזק לשנייה ורדיוס הפיצוץ גדל ב־4 בכל דרגה.',unit:'נזק שריפה / שנ׳',value:l=>5+l*3},
 {key:'eskill',hero:2,group:'heroes',name:'מוליך סערה',base:65,icon:'ϟ',desc:'כל דרגה מחזקת את נזק החשמל ב־4%. בכל שתי דרגות נפתחת קפיצה נוספת לברק.',unit:'מטרות בשרשרת',value:l=>2+Math.floor(l/2)},
 {key:'iskill',hero:3,group:'heroes',name:'כפור עמוק',base:55,icon:'❄',desc:'ההאטה מתחזקת ב־3 נקודות אחוז בכל דרגה. מאפשרת לצוות יותר זמן לפגוע באויבים.',unit:'% האטה',value:l=>42+l*3}
];
export function buyUpgrade(save,key){const def=SHOP.find(d=>d.key===key);if(!def||save[key]>=8)return false;const cost=Math.round(def.base*1.65**save[key]);if(save.coins<cost)return false;save.coins-=cost;save[key]++;return true;}

export function heroProgress(save,id){const def=HEROES.find(h=>h.id===id);const training=def?.trainingKey?(save[def.trainingKey]||0)+(save[{gunner:'reload',fire:'fskill',electric:'eskill',frost:'iskill'}[def.archetype]]||0):0;const record=save.heroes?.[id]||{};let xp=(record.xp||0)+(training+heroCardRank(save,id))*30,level=1,needed=80;while(xp>=needed&&level<20){xp-=needed;level++;needed=80+(level-1)*40;}return {level,xp,needed,percent:level===20?100:xp/needed*100,bonus:(level-1)*3,seconds:record.seconds||0,score:record.score||0,runs:record.runs||0};}
export const GADGETS={gunner:{name:'מחסנית מורחבת',desc:'עוד 3 קליעים למחסנית בכל דרגה',apply:h=>{h.mag+=3;h.ammo+=3}},fire:{name:'מאיץ בעירה',desc:'עוד 5 נזק שריפה ו־10 לרדיוס בכל דרגה',apply:h=>{h.burn+=5;h.radius+=10}},electric:{name:'סליל תהודה',desc:'עוד מטרת שרשרת, עד 6, ו־10% נזק בכל דרגה',apply:h=>{h.chain=Math.min(6,h.chain+1);h.damage*=1.1}},frost:{name:'שעון כפור',desc:'קיצור 15% בהמתנה להקפאה בכל דרגה',apply:h=>h.specialCooldown*=.85}};
